/**
 * PXD Sidebar — left-rail navigation organism.
 * Ported from the pxd-sidebar web component (templates/pictet-prototype),
 * re-themed onto PXD design tokens (colors_and_type.css) instead of the
 * hardcoded hex values the prototype used. Behaviour/geometry rules are
 * unchanged: square 104×104 rail items, up to 3 stacked 360px flyout panels,
 * always-present Feedback cell + Pictet brand mark pinned to the bottom,
 * and a mobile drawer (drill-down list) when `overlay` is set.
 */
const CSS = `
.pxd-sbar { position: relative; display: flex; height: 100%; font-family: var(--font-sans); color: var(--grey-default); }
.pxd-sbar * { box-sizing: border-box; }

.pxd-sbar-rail {
  position: relative;
  width: 104px;
  height: 100%;
  background: var(--white-default);
  border-right: 1px solid var(--grey-border-default);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  z-index: 2;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.pxd-sbar-rail::-webkit-scrollbar { width: 0; height: 0; display: none; }
.pxd-sbar-overlay-scrollbar {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 2px;
  width: 4px;
  pointer-events: none;
  opacity: 0;
  transition: opacity .22s ease;
  z-index: 4;
}
.pxd-sbar-overlay-scrollbar[data-visible="true"] { opacity: 1; }
.pxd-sbar-overlay-thumb {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 0;
  background-color: rgba(62,62,62,0.45);
  border-radius: 999px;
}
.pxd-sbar-main { flex: 1 1 auto; display: flex; flex-direction: column; }
.pxd-sbar-footer { flex: 0 0 auto; display: flex; flex-direction: column; }

.pxd-sbar-item {
  position: relative;
  width: 104px;
  height: 104px;
  flex: 0 0 auto;
  background: transparent;
  border: 0;
  border-left: 4px solid transparent;
  padding: var(--spacing-sm) var(--spacing-sm) var(--spacing-sm) 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  cursor: pointer;
  color: var(--grey-default);
  text-align: center;
  transition: background-color .12s ease, color .12s ease;
  outline: none;
  font-family: inherit;
}
.pxd-sbar-item:hover { background: var(--accent-hover-default); color: var(--accent-default); }
.pxd-sbar-item:focus-visible { outline: 2px solid var(--accent-default); outline-offset: -4px; }
.pxd-sbar-item[data-selected="true"] {
  background: var(--accent-selected);
  color: var(--accent-default);
  border-left-color: var(--accent-default);
}
.pxd-sbar-item[data-selected="true"] .pxd-sbar-label { font-weight: 700; }
.pxd-sbar-icon-wrap { position: relative; display: inline-flex; }
.pxd-sbar-icon {
  font-family: 'Material Symbols Outlined';
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  font-weight: normal;
  font-size: 24px;
  line-height: 1;
  width: 24px;
  height: 24px;
  text-align: center;
  color: inherit;
}
.pxd-sbar-label {
  font-size: 14px;
  line-height: 20px;
  color: inherit;
  width: 100%;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-word;
}
.pxd-sbar-badge {
  position: absolute;
  top: -4px;
  right: -10px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: var(--status-error-default);
  color: var(--white-default);
  font-size: 10px;
  font-weight: 700;
  line-height: 16px;
  text-align: center;
}
.pxd-sbar-feedback {
  position: relative;
  width: 104px;
  height: 104px;
  flex: 0 0 auto;
  background: transparent;
  border: 0;
  border-left: 4px solid transparent;
  padding: var(--spacing-sm) var(--spacing-sm) var(--spacing-sm) 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  cursor: pointer;
  color: var(--grey-default);
  text-align: center;
  font-family: inherit;
  transition: background-color .12s ease, color .12s ease;
}
.pxd-sbar-feedback:hover { background: var(--accent-hover-default); color: var(--accent-default); }
.pxd-sbar-brand {
  flex: 0 0 auto;
  width: 104px;
  height: 104px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-pictet);
  user-select: none;
  pointer-events: none;
}
.pxd-sbar-brand svg { display: block; }

.pxd-sbar-tooltip {
  position: absolute;
  width: 300px;
  background: var(--grey-default);
  color: var(--white-default);
  padding: var(--spacing-md);
  border-radius: var(--border-radius-xs);
  box-shadow: 0 -1px 1.5px rgba(0,0,0,0.1), 0 3px 3px rgba(0,0,0,0.12);
  font-size: 14px;
  line-height: 20px;
  text-align: center;
  pointer-events: none;
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity .12s ease, transform .12s ease;
  z-index: 5;
  left: 100px;
}
.pxd-sbar-tooltip[data-visible="true"] { opacity: 1; transform: translateX(0); }
.pxd-sbar-tooltip::before {
  content: ''; position: absolute; left: -6px; top: 24px; width: 0; height: 0;
  border-top: 5px solid transparent; border-bottom: 5px solid transparent;
  border-right: 6px solid var(--grey-default);
}

.pxd-sbar-panels { position: absolute; top: 0; left: 104px; height: 100%; display: flex; z-index: 3; pointer-events: none; }
.pxd-sbar-panel {
  pointer-events: auto;
  width: 360px;
  height: 100%;
  background: var(--white-default);
  border-right: 1px solid var(--grey-border-default);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md-nudge);
  overflow: hidden;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.04), 6px 0 10px rgba(0,0,0,0.08);
  animation: pxd-sbar-panel-slide .18s cubic-bezier(.2,.7,.3,1) both;
}
@keyframes pxd-sbar-panel-slide { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: translateX(0); } }
.pxd-sbar-panel[data-variant="cream"] { background: var(--offwhite-default-zebra); }
.pxd-sbar-panel-title { font-size: 16px; line-height: 24px; font-weight: 700; margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pxd-sbar-panel-close {
  position: absolute; top: var(--spacing-md); right: var(--spacing-md); width: 24px; height: 24px;
  border: 0; background: transparent; color: var(--grey-default); cursor: pointer;
  border-radius: var(--border-radius-xs); display: inline-flex; align-items: center; justify-content: center;
}
.pxd-sbar-panel-close:hover { background: var(--accent-hover-default); }
.pxd-sbar-sublevels { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; scrollbar-width: thin; }
.pxd-sbar-subitem {
  display: flex; align-items: center; flex: 0 0 40px; height: 40px; padding: var(--spacing-sm);
  border-radius: var(--border-radius-xs); cursor: pointer; background: transparent; border: 0; width: 100%;
  text-align: left; color: var(--grey-default); font-size: 14px; line-height: 20px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  transition: background-color .1s ease, color .1s ease; font-family: inherit;
}
.pxd-sbar-subitem:hover { background: var(--accent-hover-default); color: var(--accent-default); }
.pxd-sbar-subitem[data-selected="true"] { color: var(--accent-default); font-weight: 700; }

/* ── Overlay (mobile) drawer ─────────────────────────────────────────── */
.pxd-sbar-backdrop {
  position: fixed; inset: 0; background: rgba(0,0,0,0.45); opacity: 0; pointer-events: none;
  transition: opacity .22s ease; z-index: 99;
}
.pxd-sbar-backdrop[data-open="true"] { opacity: 1; pointer-events: auto; }
.pxd-sbar-drawer {
  position: fixed; top: 0; left: 0; bottom: 0; width: 320px; max-width: 86vw;
  background: var(--white-default); z-index: 100; transform: translateX(-100%);
  transition: transform .22s ease; display: flex; flex-direction: column; overflow: hidden;
}
.pxd-sbar-drawer[data-open="true"] { transform: translateX(0); }
.pxd-sbar-mlevel { position: absolute; inset: 0; display: flex; flex-direction: column; background: var(--white-default); transition: transform .28s cubic-bezier(.4,0,.2,1); }
.pxd-sbar-mlevel-sub { transform: translateX(100%); }
.pxd-sbar-drawer[data-state="sub"] .pxd-sbar-mlevel-root { transform: translateX(-100%); }
.pxd-sbar-drawer[data-state="sub"] .pxd-sbar-mlevel-sub { transform: translateX(0); }
.pxd-sbar-mscroll { flex: 1 1 auto; overflow-y: auto; }
.pxd-sbar-mitem {
  width: 100%; display: flex; align-items: center; gap: var(--spacing-md); padding: var(--spacing-md);
  min-height: 56px; background: transparent; color: var(--grey-default); border: 0; text-align: left;
  cursor: pointer; font: inherit; font-size: 16px; line-height: 1.3;
}
.pxd-sbar-mitem:hover { background: var(--accent-hover-default); }
.pxd-sbar-mitem[data-selected="true"] {
  background: var(--accent-selected); color: var(--accent-default); font-weight: 700;
  box-shadow: inset 4px 0 0 var(--accent-default);
}
.pxd-sbar-mitem .pxd-sbar-icon { flex: 0 0 24px; }
.pxd-sbar-mlabel { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pxd-sbar-mchevron { flex: 0 0 24px; font-family: 'Material Symbols Outlined'; font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24; font-size: 24px; color: var(--grey-400); }
.pxd-sbar-mheader { flex: 0 0 auto; display: flex; align-items: center; gap: var(--spacing-sm); padding: var(--spacing-sm) var(--spacing-md); min-height: 56px; border-bottom: 1px solid var(--grey-border-default); }
.pxd-sbar-mback { background: none; border: 0; cursor: pointer; width: 40px; height: 40px; border-radius: var(--border-radius-xs); display: flex; align-items: center; justify-content: center; color: var(--grey-default); }
.pxd-sbar-mback:hover { background: var(--accent-hover-default); color: var(--accent-default); }
.pxd-sbar-msubtitle { flex: 1 1 auto; font-size: 18px; font-weight: 700; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pxd-sbar-msection-title { padding: var(--spacing-2xl) var(--spacing-md) var(--spacing-sm); font-size: 12px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--grey-500); }
.pxd-sbar-msection[data-variant="cream"] { background: var(--offwhite-default-zebra); }
.pxd-sbar-mfooter { flex: 0 0 auto; border-top: 1px solid var(--grey-border-default); }
.pxd-sbar-mbrand { display: flex; align-items: center; gap: var(--spacing-md); padding: var(--spacing-md); color: var(--brand-pictet); }
.pxd-sbar-mbrand svg { width: 28px; height: 32px; flex: 0 0 auto; }
.pxd-sbar-mversion { font-size: 12px; color: var(--grey-500); }
`;
